-- Fixed public conversion caller profiles;synthetic values only.
DECLARE @ExpectedApiCount int=16;
INSERT @Apis VALUES
(1,N'toolbelt_conversion',N'TVF_Base64Encode','SELECT',N'SELECT * FROM toolbelt_conversion.TVF_Base64Encode(0xFBFF,DEFAULT);',N'DECLARE @Rows table(EncodedValue varchar(max) NULL); INSERT @Rows SELECT EncodedValue FROM toolbelt_conversion.TVF_Base64Encode(0xFBFF,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DATALENGTH(EncodedValue)=4 AND CONVERT(varbinary(max),EncodedValue)=CONVERT(varbinary(max),''+/8='')) THROW 52097,N''Conversion fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT EncodedValue FROM toolbelt_conversion.TVF_Base64Encode(NULL,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE EncodedValue IS NULL) THROW 52097,N''Conversion NULL oracle.'',13; '),
(2,N'toolbelt_conversion',N'TVF_Base64Decode','SELECT',N'SELECT * FROM toolbelt_conversion.TVF_Base64Decode(''+/8='');',N'DECLARE @Rows table(DecodedValue varbinary(max) NULL); INSERT @Rows SELECT DecodedValue FROM toolbelt_conversion.TVF_Base64Decode(''+/8=''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DATALENGTH(DecodedValue)=2 AND DecodedValue=0xFBFF) THROW 52097,N''Conversion fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT DecodedValue FROM toolbelt_conversion.TVF_Base64Decode(NULL); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DecodedValue IS NULL) THROW 52097,N''Conversion NULL oracle.'',13; '),
(3,N'toolbelt_conversion',N'TVF_Base64EncodeStatus','SELECT',N'SELECT * FROM toolbelt_conversion.TVF_Base64EncodeStatus(0xFBFF,DEFAULT);',N'DECLARE @Rows table(EncodedValue varchar(max) NULL,Status varchar(16) NULL); INSERT @Rows SELECT EncodedValue,Status FROM toolbelt_conversion.TVF_Base64EncodeStatus(0xFBFF,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DATALENGTH(EncodedValue)=4 AND CONVERT(varbinary(max),EncodedValue)=CONVERT(varbinary(max),''+/8='') AND Status=''OK'') THROW 52097,N''Conversion fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT EncodedValue,Status FROM toolbelt_conversion.TVF_Base64EncodeStatus(NULL,DEFAULT); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE EncodedValue IS NULL AND Status=''SQL_NULL'') THROW 52097,N''Conversion NULL oracle.'',13; '),
(4,N'toolbelt_conversion',N'TVF_Base64DecodeStatus','SELECT',N'SELECT * FROM toolbelt_conversion.TVF_Base64DecodeStatus(''+/8='');',N'DECLARE @Rows table(DecodedValue varbinary(max) NULL,Status varchar(16) NULL); INSERT @Rows SELECT DecodedValue,Status FROM toolbelt_conversion.TVF_Base64DecodeStatus(''+/8=''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DATALENGTH(DecodedValue)=2 AND DecodedValue=0xFBFF AND Status=''OK'') THROW 52097,N''Conversion fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT DecodedValue,Status FROM toolbelt_conversion.TVF_Base64DecodeStatus(NULL); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DecodedValue IS NULL AND Status=''SQL_NULL'') THROW 52097,N''Conversion NULL oracle.'',13; DELETE @Rows; INSERT @Rows SELECT DecodedValue,Status FROM toolbelt_conversion.TVF_Base64DecodeStatus(''!''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DecodedValue IS NULL AND Status=''INVALID'') THROW 52097,N''Conversion invalid status oracle.'',16;'),
(5,N'toolbelt_conversion',N'SVF_Base64Encode','EXECUTE',N'SELECT toolbelt_conversion.SVF_Base64Encode(0xFBFF,DEFAULT);',N'DECLARE @V varchar(max)=toolbelt_conversion.SVF_Base64Encode(0xFBFF,DEFAULT); IF @V IS NULL OR NOT(DATALENGTH(@V)=DATALENGTH(''+/8='') AND CONVERT(varbinary(max),@V)=CONVERT(varbinary(max),''+/8='')) THROW 52097,N''Conversion scalar value oracle.'',14; IF toolbelt_conversion.SVF_Base64Encode(NULL,DEFAULT) IS NOT NULL THROW 52097,N''Conversion scalar NULL oracle.'',15;'),
(6,N'toolbelt_conversion',N'SVF_Base64Decode','EXECUTE',N'SELECT toolbelt_conversion.SVF_Base64Decode(''+/8='');',N'DECLARE @V varbinary(max)=toolbelt_conversion.SVF_Base64Decode(''+/8=''); IF @V IS NULL OR NOT(DATALENGTH(@V)=DATALENGTH(0xFBFF) AND CONVERT(varbinary(max),@V)=CONVERT(varbinary(max),0xFBFF)) THROW 52097,N''Conversion scalar value oracle.'',14; IF toolbelt_conversion.SVF_Base64Decode(NULL) IS NOT NULL THROW 52097,N''Conversion scalar NULL oracle.'',15;'),
(7,N'toolbelt_conversion',N'TVF_IntegerToBase','SELECT',N'SELECT * FROM toolbelt_conversion.TVF_IntegerToBase(CONVERT(bigint,''-9223372036854775808''),''0123456789'');',N'DECLARE @Rows table(EncodedValue varchar(65) NULL); INSERT @Rows SELECT EncodedValue FROM toolbelt_conversion.TVF_IntegerToBase(CONVERT(bigint,''-9223372036854775808''),''0123456789''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DATALENGTH(EncodedValue)=20 AND CONVERT(varbinary(max),EncodedValue)=CONVERT(varbinary(max),''-9223372036854775808'')) THROW 52097,N''Conversion fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT EncodedValue FROM toolbelt_conversion.TVF_IntegerToBase(NULL,''0123456789''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE EncodedValue IS NULL) THROW 52097,N''Conversion NULL oracle.'',13; '),
(8,N'toolbelt_conversion',N'TVF_TryBaseToInteger','SELECT',N'SELECT * FROM toolbelt_conversion.TVF_TryBaseToInteger(''+'',''01+'');',N'DECLARE @Rows table(DecodedValue bigint NULL); INSERT @Rows SELECT DecodedValue FROM toolbelt_conversion.TVF_TryBaseToInteger(''+'',''01+''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DecodedValue=2) THROW 52097,N''Conversion fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT DecodedValue FROM toolbelt_conversion.TVF_TryBaseToInteger(NULL,''01+''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DecodedValue IS NULL) THROW 52097,N''Conversion NULL oracle.'',13; DELETE @Rows; INSERT @Rows SELECT DecodedValue FROM toolbelt_conversion.TVF_TryBaseToInteger(''9223372036854775808'',''0123456789''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DecodedValue IS NULL) THROW 52097,N''Conversion overflow oracle.'',17;'),
(9,N'toolbelt_conversion',N'SVF_IntegerToBase','EXECUTE',N'SELECT toolbelt_conversion.SVF_IntegerToBase(CONVERT(bigint,''-9223372036854775808''),''0123456789'');',N'DECLARE @V varchar(65)=toolbelt_conversion.SVF_IntegerToBase(CONVERT(bigint,''-9223372036854775808''),''0123456789''); IF @V IS NULL OR NOT(DATALENGTH(@V)=DATALENGTH(''-9223372036854775808'') AND CONVERT(varbinary(max),@V)=CONVERT(varbinary(max),''-9223372036854775808'')) THROW 52097,N''Conversion scalar value oracle.'',14; IF toolbelt_conversion.SVF_IntegerToBase(NULL,''0123456789'') IS NOT NULL THROW 52097,N''Conversion scalar NULL oracle.'',15;'),
(10,N'toolbelt_conversion',N'SVF_TryBaseToInteger','EXECUTE',N'SELECT toolbelt_conversion.SVF_TryBaseToInteger(''+'',''01+'');',N'DECLARE @V bigint=toolbelt_conversion.SVF_TryBaseToInteger(''+'',''01+''); IF @V IS NULL OR NOT(@V=2) THROW 52097,N''Conversion scalar value oracle.'',14; IF toolbelt_conversion.SVF_TryBaseToInteger(NULL,''01+'') IS NOT NULL THROW 52097,N''Conversion scalar NULL oracle.'',15;'),
(11,N'toolbelt_conversion',N'TVF_UriComponentEncode','SELECT',N'SELECT * FROM toolbelt_conversion.TVF_UriComponentEncode(N''Kaffee & Tee'');',N'DECLARE @Rows table(EncodedValue nvarchar(max) NULL); INSERT @Rows SELECT EncodedValue FROM toolbelt_conversion.TVF_UriComponentEncode(N''Kaffee & Tee''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DATALENGTH(EncodedValue)=DATALENGTH(N''Kaffee%20%26%20Tee'') AND CONVERT(varbinary(max),EncodedValue)=CONVERT(varbinary(max),N''Kaffee%20%26%20Tee'')) THROW 52097,N''Conversion fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT EncodedValue FROM toolbelt_conversion.TVF_UriComponentEncode(NULL); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE EncodedValue IS NULL) THROW 52097,N''Conversion NULL oracle.'',13; '),
(12,N'toolbelt_conversion',N'TVF_UriComponentDecode','SELECT',N'SELECT * FROM toolbelt_conversion.TVF_UriComponentDecode(N''%E2%82%AC%20%2B'');',N'DECLARE @Rows table(DecodedValue nvarchar(max) NULL,IsValid bit NULL,ValidationCode tinyint NULL); INSERT @Rows SELECT DecodedValue,IsValid,ValidationCode FROM toolbelt_conversion.TVF_UriComponentDecode(N''%E2%82%AC%20%2B''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DATALENGTH(DecodedValue)=DATALENGTH(N''€ +'') AND CONVERT(varbinary(max),DecodedValue)=CONVERT(varbinary(max),N''€ +'') AND IsValid=1 AND ValidationCode=0) THROW 52097,N''Conversion fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT DecodedValue,IsValid,ValidationCode FROM toolbelt_conversion.TVF_UriComponentDecode(NULL); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DecodedValue IS NULL AND IsValid IS NULL AND ValidationCode IS NULL) THROW 52097,N''Conversion NULL oracle.'',13; '),
(13,N'toolbelt_conversion',N'TVF_UriComponentEncodeStatus','SELECT',N'SELECT * FROM toolbelt_conversion.TVF_UriComponentEncodeStatus(N''Kaffee & Tee'');',N'DECLARE @Rows table(EncodedValue nvarchar(max) NULL,Status varchar(16) NULL); INSERT @Rows SELECT EncodedValue,Status FROM toolbelt_conversion.TVF_UriComponentEncodeStatus(N''Kaffee & Tee''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DATALENGTH(EncodedValue)=DATALENGTH(N''Kaffee%20%26%20Tee'') AND CONVERT(varbinary(max),EncodedValue)=CONVERT(varbinary(max),N''Kaffee%20%26%20Tee'') AND Status=''OK'') THROW 52097,N''Conversion fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT EncodedValue,Status FROM toolbelt_conversion.TVF_UriComponentEncodeStatus(NULL); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE EncodedValue IS NULL AND Status=''SQL_NULL'') THROW 52097,N''Conversion NULL oracle.'',13; '),
(14,N'toolbelt_conversion',N'TVF_UriComponentDecodeStatus','SELECT',N'SELECT * FROM toolbelt_conversion.TVF_UriComponentDecodeStatus(N''%E2%82%AC%20%2B'');',N'DECLARE @Rows table(DecodedValue nvarchar(max) NULL,IsValid bit NULL,ValidationCode tinyint NULL,Status varchar(16) NULL); INSERT @Rows SELECT DecodedValue,IsValid,ValidationCode,Status FROM toolbelt_conversion.TVF_UriComponentDecodeStatus(N''%E2%82%AC%20%2B''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DATALENGTH(DecodedValue)=DATALENGTH(N''€ +'') AND CONVERT(varbinary(max),DecodedValue)=CONVERT(varbinary(max),N''€ +'') AND IsValid=1 AND ValidationCode=0 AND Status=''OK'') THROW 52097,N''Conversion fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT DecodedValue,IsValid,ValidationCode,Status FROM toolbelt_conversion.TVF_UriComponentDecodeStatus(NULL); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DecodedValue IS NULL AND IsValid IS NULL AND ValidationCode IS NULL AND Status=''SQL_NULL'') THROW 52097,N''Conversion NULL oracle.'',13; DELETE @Rows; INSERT @Rows SELECT DecodedValue,IsValid,ValidationCode,Status FROM toolbelt_conversion.TVF_UriComponentDecodeStatus(N''%GG''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DecodedValue IS NULL AND IsValid=0 AND ValidationCode=11 AND Status=''INVALID'') THROW 52097,N''Conversion percent oracle.'',18;'),
